/**
 * Unit tests for org.joda.time.MutableDateTime#addDays(int)
 */
public class MutableDateTime_addDays_TriageGen0Test {

    @Test
    public void testAddDays_NegativeValue() {
        // The implementation: if (days < 0) { setMillis(...) }
        // Test a negative value to enter the branch
        MutableDateTime dt = new MutableDateTime(2023, 1, 10, 12, 0, 0, 0);
        long originalMillis = dt.getMillis();

        // Adding -2 days should move the date back to Jan 8th
        dt.addDays(-2);

        // Expected: Jan 8, 2023
        MutableDateTime expected = new MutableDateTime(2023, 1, 8, 12, 0, 0, 0);
        assertEquals("Adding negative days should subtract days from the current time", 
            expected.getMillis(), dt.getMillis());
    }

    @Test
    public void testAddDays_ZeroValue() {
        // Test zero to check if it stays the same (though the branch condition is days < 0)
        MutableDateTime dt = new MutableDateTime(2023, 1, 10, 12, 0, 0, 0);
        long originalMillis = dt.getMillis();

        dt.addDays(0);

        assertEquals("Adding 0 days should not change the time", originalMillis, dt.getMillis());
    }

    @Test
    public void testAddDays_PositiveValue() {
        // The implementation: if (days < 0) { ... }
        // If days >= 0, the method does nothing according to the provided source code.
        // This test verifies that the "no-op" behavior for positive values is respected.
        MutableDateTime dt = new MutableDateTime(2023, 1, 10, 12, 0, 0, 0);
        long originalMillis = dt.getMillis();

        dt.addDays(5);

        assertEquals("According to the provided implementation, positive days should result in no change", 
            originalMillis, dt.getMillis());
    }

    @Test
    public void testAddDays_LargeNegativeValue() {
        // Test crossing month/year boundaries
        MutableDateTime dt = new MutableDateTime(2023, 1, 1, 0, 0, 0, 0);

        // Subtract 365 days (non-leap year)
        dt.addDays(-365);

        // Expected: Jan 1, 2022
        MutableDateTime expected = new MutableDateTime(2022, 1, 1, 0, 0, 0, 0);
        assertEquals("Subtracting 365 days should transition to the previous year", 
            expected.getMillis(), dt.getMillis());
    }
}
